import { Img, staticFile, useCurrentFrame } from 'remotion';

type Props = {
  /** 0 closed .. 1 wide open (see `mouthOpenAt`): drives a tiny "talking" pulse. */
  mouthOpen: number;
  /** Rendered width in px. */
  size?: number;
  /** Height shown in px: the image is cut by the bottom edge of the frame (bust shot). */
  visibleHeight?: number;
};

const SOURCE = { width: 1199, height: 1312 } as const;
/** Where "DEV" sits on the t-shirt, in source-image pixels. */
const DEV_TEXT = { x: 712, y: 845, size: 72, rotate: -2 } as const;

/**
 * The channel's mascot (AI-generated by the owner, see public/music/LICENSES.md): a young developer with a
 * laptop, standing at the bottom edge of the frame. It sways, and pulses slightly while the narrator speaks.
 */
export const Mascot: React.FC<Props> = ({ mouthOpen, size = 470, visibleHeight = 405 }) => {
  const frame = useCurrentFrame();
  // Only ever moves down, so the cut body never leaves a gap above the bottom edge of the frame.
  const bob = (Math.sin(frame / 14) + 1) * 3;
  const tilt = Math.sin(frame / 37) * 1.2;
  const pulse = 1 + mouthOpen * 0.012;
  const height = (size * SOURCE.height) / SOURCE.width;

  return (
    <div style={{ width: size, height: visibleHeight, overflow: 'hidden', position: 'relative' }}>
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          width: size,
          height,
          transform: `translateY(${bob}px) rotate(${tilt}deg) scale(${pulse})`,
          transformOrigin: '50% 100%',
        }}
      >
        <Img
          src={staticFile('mascot/default.png')}
          style={{ width: size, height, filter: 'none' }}
        />
        {/* "DEV" printed on the white t-shirt (drawn in the image's own coordinates, so it scales with it) */}
        <svg
          viewBox={`0 0 ${SOURCE.width} ${SOURCE.height}`}
          width={size}
          height={height}
          style={{ position: 'absolute', left: 0, top: 0 }}
        >
          <text
            x={DEV_TEXT.x}
            y={DEV_TEXT.y}
            textAnchor="middle"
            fontSize={DEV_TEXT.size}
            fontWeight={900}
            letterSpacing={4}
            fill="#14143a"
            transform={`rotate(${DEV_TEXT.rotate} ${DEV_TEXT.x} ${DEV_TEXT.y})`}
            fontFamily='"Be Vietnam Pro", sans-serif'
          >
            DEV
          </text>
        </svg>
      </div>
    </div>
  );
};
